def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(obj, default=None):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def clamp_move(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    env = observation.get("environment_name", "") if isinstance(observation, dict) else ""
    sx, sy = pos(observation.get("self_position", (0, 0)) if isinstance(observation, dict) else (0, 0), (0, 0))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)) if isinstance(observation, dict) else (sx, sy), (sx, sy))
    w = observation.get("grid_width", 0) if isinstance(observation, dict) else 0
    h = observation.get("grid_height", 0) if isinstance(observation, dict) else 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") if isinstance(observation, dict) else "pursuer"
        if role == "pursuer":
            return clamp_move((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return clamp_move((sx, sy), target)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "target_cells"):
            cells = observation.get(key, []) if isinstance(observation, dict) else []
            if cells:
                candidates = cells
                break
        if not candidates:
            return [sgn(ox - sx), sgn(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]
        best = min(candidates, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return clamp_move((sx, sy), best)

    resources = []
    if isinstance(observation, dict):
        for key in ("resources", "resource_positions", "targets", "food"):
            items = observation.get(key, [])
            if items:
                resources = items
                break

    if resources:
        best = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return clamp_move((sx, sy), best)

    if isinstance(observation, dict):
        allies = observation.get("allied_positions", []) or observation.get("teammate_positions", [])
        if allies:
            tx, ty = pos(allies[0], (sx, sy))
            return clamp_move((sx, sy), (tx, ty))

    return [sgn(ox - sx), sgn(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]

